import json
def solve(g):
    H=len(g);W=len(g[0])
    # find full separator row(s) and col(s)
    sep_r=[r for r in range(H) if all(x==g[r][0] for x in g[r])]
    sep_c=[c for c in range(W) if all(g[r][c]==g[0][c] for r in range(H))]
    blocks=[]
    rs=[-1]+sep_r+[H]
    cs=[-1]+sep_c+[W]
    for i in range(len(rs)-1):
        for j in range(len(cs)-1):
            blocks.append((rs[i]+1,rs[i+1]-1,cs[j]+1,cs[j+1]-1))
    # template = block with most nonzero cells (not uniform color?) - pick block containing multiple colors
    def score(b):
        r0,r1,c0,c1=b
        return sum(1 for r in range(r0,r1+1) for c in range(c0,c1+1) if g[r][c]!=g[b[0]][b[0]] if g[r][c]!=2 or True)
    # simpler: template block = one whose non-separator cells aren't all same value
    t=None
    for b in blocks:
        vals={g[r][c] for r in range(*b[0],*b[0][2:])} if False else {g[r][c] for r in range(b[0],b[1]+1) for c in range(b[2],b[3]+1)}
        if len(vals)>1: t=b; break
    r0,r1,c0,c1=t
    pat=[[g[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    out=[row[:] for row in g]
    for br0,br1,bc0,bc1 in blocks:
        for r in range(br0,br1+1):
            for c in range(bc0,bc1+1):
                out[r][c]=pat[r-br0][c-bc0]
    return out
